#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum DomainEvent {
    // === Indexing Events ===
    /// Index rebuild requested or completed
    IndexRebuild {
        /// Collection being rebuilt (None = all collections)
        collection: Option<String>,
    },
    /// Indexing operation started
    IndexingStarted {
        /// Collection being indexed
        collection: String,
        /// Total number of files to process
        total_files: usize,
    },
    /// Indexing progress update
    IndexingProgress {
        /// Collection being indexed
        collection: String,
        /// Files processed so far
        processed: usize,
        /// Total files to process
        total: usize,
        /// Current file being processed
        current_file: Option<String>,
    },
    /// Indexing operation completed
    IndexingCompleted {
        /// Collection that was indexed
        collection: String,
        /// Total chunks created
        chunks: usize,
        /// Duration in milliseconds
        duration_ms: u64,
    },

    // === Sync Events ===
    /// Sync operation completed
    SyncCompleted {
        /// Path that was synced
        path: String,
        /// Number of files that changed
        files_changed: i32,
    },

    // === Cache Events ===
    /// Cache invalidation requested
    CacheInvalidate {
        /// Namespace to invalidate (None = all)
        namespace: Option<String>,
    },

    // === Snapshot Events ===
    /// Snapshot created for a codebase
    SnapshotCreated {
        /// Root path of the codebase
        root_path: String,
        /// Number of files in snapshot
        file_count: usize,
    },

    // === File Watcher Events ===
    /// File changes detected
    FileChangesDetected {
        /// Root path being monitored
        root_path: String,
        /// Number of added files
        added: usize,
        /// Number of modified files
        modified: usize,
        /// Number of removed files
        removed: usize,
    },

    // === Service Lifecycle Events ===
    /// Service state changed
    ServiceStateChanged {
        /// Name of the service
        name: String,
        /// New state
        state: ServiceState,
        /// Previous state (if known)
        previous_state: Option<ServiceState>,
    },

    // === Configuration Events ===
    /// Configuration section reloaded
    ConfigReloaded {
        /// Section that was reloaded
        section: String,
        /// Timestamp of reload
        timestamp: DateTime<Utc>,
    },

    // === Health Events ===
    /// Health check completed
    HealthCheckCompleted {
        /// Overall status
        status: String,
        /// Number of healthy dependencies
        healthy_count: usize,
        /// Number of unhealthy dependencies
        unhealthy_count: usize,
    },

    // === Metrics Events ===
    /// Periodic metrics snapshot
    MetricsSnapshot {
        /// Timestamp of snapshot
        timestamp: DateTime<Utc>,
    },

    // === Search Events ===
    /// Search query executed
    SearchExecuted {
        /// Search query
        query: String,
        /// Collection searched
        collection: String,
        /// Number of results
        results: usize,
        /// Duration in milliseconds
        duration_ms: u64,
    },
}

